SELECT CASE WHEN credit_limit >= 15700 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_tier, country, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, STDDEV_SAMP(age) AS age_stddev, BIT_OR(age) AS age_bit_or, PERCENTILE_APPROX(age, ARRAY(0.25, 0.5, 0.75)) AS age_quartiles, APPROX_PERCENTILE(credit_limit, ARRAY(0.25, 0.5, 0.75)) AS credit_limit_quartiles, RANK() OVER (PARTITION BY CASE WHEN credit_limit >= 15700 THEN 'HIGH' ELSE 'LOW' END ORDER BY STDDEV_SAMP(age) DESC) AS age_stddev_rank FROM customers GROUP BY CASE WHEN credit_limit >= 15700 THEN 'HIGH' ELSE 'LOW' END, country HAVING age_stddev >= 0 ORDER BY credit_limit_tier DESC;
